 resetCatalogContext(){this.codeSearch={kind:'',query:''};this.codeHistory=null;const fileInput=document.getElementById('catalog-import-file');if(fileInput)fileInput.value='';this.catalogFile=null;this.catalogMeta=emptyCatalogImport();this.catalogReceiveReason='';this.catalogReceiveAttempt=null;this.catalogImports=[];this.catalogImport=null;this.catalogQuery='';this.catalogSelected=[];this.catalogFrom='';this.catalogPreview=null;this.catalogApplications=[];this.catalogReviewReference='';this.catalogApplyReason='';this.catalogConfirmed=false;this.catalogLegacyAcknowledged=false;this.catalogApplyAttempt=null;},
