 async receiveCatalog(){await this.run(async()=>{const file=this.catalogFile,company=this.company;if(!file||file.size>8*1024*1024)throw Error('Selecione CSV ou JSON do padrão, até 8 MiB.');const bytes=new Uint8Array(await file.arrayBuffer());let binary='';for(let i=0;i<bytes.length;i+=8192)binary+=String.fromCharCode(...bytes.subarray(i,i+8192));const rawHash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))).map(b=>b.toString(16).padStart(2,'0')).join('');const signature=JSON.stringify([company,file.name,rawHash,this.catalogMeta,this.catalogReceiveReason]);if(this.catalogReceiveAttempt?.signature!==signature)this.catalogReceiveAttempt={signature,key:this.key()};if(company!==this.company)throw Error('A empresa mudou durante a leitura; confira o destino.');const result=await this.api('tax-catalog-imports',{company_id:company,filename:file.name,content_base64:btoa(binary),metadata:clone(this.catalogMeta),reason:this.catalogReceiveReason,request_key:this.catalogReceiveAttempt.key},'POST');this.catalogImports=await this.api('tax-catalog-imports',{company_id:company});this.catalogImport=result.import;this.catalogSelected=[];this.catalogQuery='';this.catalogPreview=null;this.catalogApplications=[];this.catalogConfirmed=false;this.catalogLegacyAcknowledged=false;this.notice='Arquivo preservado para revisão. Nenhum código foi ativado.';});},
