 setTaxCalculation(method){const spec=this.taxForm.spec,special=['ICMS_ST','ICMS_DIFAL','RETENCAO','FCP'];if(method==='documento'){delete spec.calculation;delete spec.item_treatment;if(special.includes(spec.tax))spec.tax='';return;}spec.calculation={scope:'item',method,reduction_percent:'',base_rounding:''};spec.item_treatment=spec.item_treatment||'';if(method==='st')Object.assign(spec.calculation,{margin_percent:'',deduction_field:'st_deduction',negative_policy:''});if(method==='difal')Object.assign(spec.calculation,{origin_rate:'',negative_policy:''});if(method==='retencao')spec.calculation.component_code='';if(method==='fcp')Object.assign(spec.calculation,{component_code:'',base_mode:''});if(method==='por_dentro')this.setGrossupFields(true);spec.tax=({st:'ICMS_ST',difal:'ICMS_DIFAL',retencao:'RETENCAO',fcp:'FCP'})[method]||(special.includes(spec.tax)?'':spec.tax);},
