 useDocumentTaxMode(){const p=this.active?.data.payload;if(!p)return;if(p.tax_calculation){this.error='Prepare a exceção motivada antes de retirar os itens de uma memória aplicada.';return;}delete p.tax_items;delete p.tax_components;},
 proposeSourceTaxItems(){const p=this.active?.data.payload;const document=this.overview?.documents.find(d=>d.id===p?.document_id);const observation=document?.source.observations.find(o=>o.id===p.observation_id);const products=observation?.raw?.products;if(!products?.length){this.error='A fonte selecionada não fornece itens estruturados. Cadastre os valores declarados manualmente.';return;}if(p.tax_items?.length){this.error='Confira ou remova os itens atuais antes de propor os vínculos da fonte.';return;}p.tax_items=products.map((product,index)=>({id:String(index+1),description:product.data.description||'',cfop:'',ncm:product.data.ncm||'',service_code:'',treatment:'',source_reference:'Fonte documental selecionada; valores e rateios exigem conferência',source_locator:product.locator,taxes:[],no_tax_reason:'',values:{total:''}}));this.notice='Vínculos e classificações observadas propostos. Informe valores líquidos, bases, componentes e rateios; nenhum valor foi presumido.';},
