 newTaxRule(){this.taxForm={rule_key:'',label:'',spec:emptyTaxSpec(),expected_version:0,reason:''};},useTaxModel(model){this.newTaxRule();this.taxForm.spec=clone(model.spec);this.taxForm.label=model.label;},editTaxRule(rule){this.taxForm={rule_key:rule.rule_key,label:rule.label,spec:clone(rule.spec),expected_version:rule.version,reason:''};},
 async reloadTax(){this.taxConfig=await this.api('tax-config',{company_id:this.company});if(this.cycle)await this.refreshSummaries();},
 async saveTaxRule(state){await this.run(async()=>{const form=clone(this.taxForm);form.spec.rate=form.spec.rate.replace(',','.');if(form.spec.calculation)for(const key of ['reduction_percent','margin_percent','origin_rate'])if(typeof form.spec.calculation[key]==='string')form.spec.calculation[key]=form.spec.calculation[key].replace(',','.');if(Array.isArray(form.spec.calculation?.denominator_components))for(const c of form.spec.calculation.denominator_components){if(c&&typeof c.component==='string')c.component=c.component.trim();if(c&&typeof c.rate==='string')c.rate=c.rate.replace(',','.');}await this.api('tax-rules',{company_id:this.company,...form,state},'POST');await this.reloadTax();this.newTaxRule();this.notice='Regra tributária versionada somente nesta empresa.';});},
