 async saveTaxTemplate(){await this.run(async()=>{const rule=this.taxConfig.rules.find(r=>String(r.id)===String(this.templateForm.rule_id));if(!rule)throw Error('Selecione uma regra aprovada.');const old=this.taxConfig.templates.find(t=>t.label===this.templateForm.label);await this.api('tax-templates',{company_id:this.company,rule_id:rule.id,rule_hash:rule.snapshot_hash,label:this.templateForm.label,expected_version:old?.version||0,reason:this.templateForm.reason},'POST');await this.reloadTax();this.notice='Modelo preservado como cópia versionada da regra.';});},
