app.component('data-table',{props:['rows','columns'],render(){if(!this.rows?.length)return Vue.h('p',{class:'empty'},'Nenhum registro neste recorte.');return Vue.h('div',{class:'table-scroll'},Vue.h('table',[Vue.h('thead',Vue.h('tr',Object.values(this.columns).map(v=>Vue.h('th',v)))),Vue.h('tbody',this.rows.map(row=>Vue.h('tr',Object.keys(this.columns).map(key=>{const v=key.split('.').reduce((o,k)=>o?.[k],row);return Vue.h('td',typeof v==='object'?JSON.stringify(v):String(v??'—'));}))))]));}});
